import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import bcrypt from 'bcryptjs';
import { prisma } from '../src/lib/prisma.js';
import { dishes } from './data/dishes/index.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const imagesPath = path.join(here, 'data', 'dish-images.json');
// Generated by prisma/fetch-dish-images.mjs; keeps the seed reproducible offline.
const dishImages = fs.existsSync(imagesPath) ? JSON.parse(fs.readFileSync(imagesPath, 'utf8')) : {};

const categories = [
  { name: 'Món nước', slug: 'mon-nuoc', description: 'Phở, bún, miến, cháo và các món có nước dùng.' },
  { name: 'Món mặn', slug: 'mon-man', description: 'Món kho, xào, nướng, chiên cho bữa cơm hằng ngày.' },
  { name: 'Bánh & ăn vặt', slug: 'banh-an-vat', description: 'Bánh dân gian, món cuốn và món ăn vặt đường phố.' },
  { name: 'Món chay', slug: 'mon-chay', description: 'Công thức không sử dụng thịt cá.' },
  { name: 'Bữa sáng', slug: 'bua-sang', description: 'Món ăn bắt đầu ngày mới.' },
  { name: 'Tráng miệng & đồ uống', slug: 'trang-mieng', description: 'Chè, bánh ngọt và đồ uống.' },
];

const tags = [
  { name: 'Món chay', slug: 'mon-chay' },
  { name: 'Thuần chay', slug: 'thuan-chay' },
  { name: 'Eat clean', slug: 'eat-clean' },
  { name: 'Dưới 30 phút', slug: 'duoi-30-phut' },
  { name: 'Không sữa', slug: 'khong-sua' },
  { name: 'Không gluten', slug: 'khong-gluten' },
  { name: 'Món Hà Nội', slug: 'mon-ha-noi' },
  { name: 'Món Huế', slug: 'mon-hue' },
  { name: 'Món Nam Bộ', slug: 'mon-nam-bo' },
  { name: 'Món miền Tây', slug: 'mien-tay' },
];

// Placeholder recipes from the first seed version, replaced by the dish catalogue.
const LEGACY_RECIPE_SLUGS = ['canh-rau-cu-thanh-mat', 'bun-tron-rau-xanh', 'yen-mach-trai-cay-buoi-sang'];
const LEGACY_CATEGORY_SLUGS = ['mon-viet'];
const FEATURED_SLUGS = new Set([
  'pho-bo', 'bun-cha', 'com-tam-suon-nuong', 'banh-mi-thit',
  'banh-xeo', 'goi-cuon', 'bun-bo-hue', 'cha-ca-la-vong',
]);
const CHALLENGE_RECIPE_SLUGS = ['pho-chay', 'dau-phu-sot-ca-chua'];

function totalMinutes(dish) {
  return (dish.prep ?? 0) + (dish.cook ?? 0);
}

async function ensureCoverImage(dish, ownerId) {
  const image = dishImages[dish.slug];
  if (!image?.secureUrl) return { id: null, hasImage: false };
  const providerPublicId = image.publicId || `recipe-community/seed/dishes/${dish.slug}`;
  const asset = await prisma.mediaAsset.upsert({
    where: { providerPublicId },
    update: {
      secureUrl: image.secureUrl,
      format: image.format || null,
      bytes: image.bytes || 0,
      status: 'ATTACHED',
      deletedAt: null,
    },
    create: {
      ownerId,
      provider: 'CLOUDINARY',
      providerPublicId,
      secureUrl: image.secureUrl,
      format: image.format || null,
      bytes: image.bytes || 0,
      status: 'ATTACHED',
      attachedAt: new Date(),
    },
  });
  return { id: asset.id, hasImage: true };
}

async function removeLegacyRecipes(authorId) {
  const legacy = await prisma.recipe.findMany({
    where: { slug: { in: LEGACY_RECIPE_SLUGS }, authorId },
    select: { id: true },
  });
  if (!legacy.length) return 0;
  const ids = legacy.map((recipe) => recipe.id);
  await prisma.challengeEntry.deleteMany({ where: { recipeId: { in: ids } } });
  await prisma.report.deleteMany({ where: { recipeId: { in: ids } } });
  await prisma.recipe.deleteMany({ where: { id: { in: ids } } });
  return ids.length;
}

async function removeEmptyLegacyCategories() {
  const legacy = await prisma.category.findMany({
    where: { slug: { in: LEGACY_CATEGORY_SLUGS } },
    select: { id: true, _count: { select: { recipes: true } } },
  });
  const emptyIds = legacy.filter((category) => category._count.recipes === 0).map((category) => category.id);
  if (!emptyIds.length) return 0;
  await prisma.category.deleteMany({ where: { id: { in: emptyIds } } });
  return emptyIds.length;
}

async function main() {
  const categoryMap = Object.fromEntries(await Promise.all(categories.map(async (category) => [
    category.slug,
    await prisma.category.upsert({ where: { slug: category.slug }, update: category, create: category }),
  ])));

  const tagMap = Object.fromEntries(await Promise.all(tags.map(async (tag) => [
    tag.slug,
    await prisma.tag.upsert({ where: { slug: tag.slug }, update: tag, create: tag }),
  ])));

  const passwordHash = await bcrypt.hash('seed-password-change-me', 12);
  const existingUser = await prisma.user.findFirst({ where: { email: 'seed@bepnha.local' } });
  const user = existingUser
    ? await prisma.user.update({ where: { id: existingUser.id }, data: { status: 'ACTIVE', role: 'EDITOR' } })
    : await prisma.user.create({
      data: {
        email: 'seed@bepnha.local',
        username: 'bepnha_seed',
        passwordHash,
        status: 'ACTIVE',
        role: 'EDITOR',
        profile: { create: { displayName: 'Bếp Nhà' } },
      },
    });

  const removed = await removeLegacyRecipes(user.id);
  if (removed) console.log(`Removed ${removed} legacy placeholder recipes.`);
  const removedCategories = await removeEmptyLegacyCategories();
  if (removedCategories) console.log(`Removed ${removedCategories} empty legacy categories.`);

  const seededRecipes = [];
  let withCover = 0;
  for (const [index, dish] of dishes.entries()) {
    const { ingredients, steps, tags: tagSlugs = [], ...data } = dish;
    const cover = await ensureCoverImage(dish, user.id);
    if (cover.hasImage) withCover += 1;

    const publishedAt = new Date(Date.now() - index * 90 * 60 * 1000);
    const recipeData = {
      title: data.title,
      slug: data.slug,
      description: data.description,
      categoryId: categoryMap[data.category]?.id ?? null,
      coverImageId: cover.id,
      prepTimeMinutes: data.prep ?? null,
      cookTimeMinutes: data.cook ?? null,
      totalTimeMinutes: totalMinutes(data),
      servings: data.servings ?? null,
      difficulty: data.difficulty ?? 'EASY',
      tips: data.tips ?? null,
      storageInstructions: data.storage ?? null,
      status: 'PUBLISHED',
      visibility: 'PUBLIC',
      publishedAt,
      featuredAt: FEATURED_SLUGS.has(data.slug) ? publishedAt : null,
      authorId: user.id,
    };

    const seeded = await prisma.$transaction(async (transaction) => {
      const saved = await transaction.recipe.upsert({
        where: { slug: data.slug },
        update: recipeData,
        create: recipeData,
      });
      await transaction.recipeIngredient.deleteMany({ where: { recipeId: saved.id } });
      await transaction.recipeStep.deleteMany({ where: { recipeId: saved.id } });
      await transaction.recipeTag.deleteMany({ where: { recipeId: saved.id } });
      await transaction.recipeIngredient.createMany({
        data: ingredients.map(([displayName, quantity, unit], sortOrder) => ({
          displayName,
          quantity: quantity ?? null,
          unit: unit ?? null,
          recipeId: saved.id,
          sortOrder,
        })),
      });
      await transaction.recipeStep.createMany({
        data: steps.map((instruction, stepIndex) => ({
          instruction,
          recipeId: saved.id,
          stepNumber: stepIndex + 1,
        })),
      });
      if (tagSlugs.length) {
        await transaction.recipeTag.createMany({
          data: tagSlugs
            .filter((slug) => tagMap[slug])
            .map((slug) => ({ recipeId: saved.id, tagId: tagMap[slug].id })),
        });
      }
      return saved;
    });
    seededRecipes.push(seeded);
  }

  const challengeTitle = 'Thử thách món chay 7 ngày';
  let challenge = await prisma.challenge.findFirst({ where: { title: challengeTitle } });
  if (!challenge) {
    challenge = await prisma.challenge.create({
      data: {
        createdById: user.id,
        title: challengeTitle,
        description: 'Chia sẻ một món chay bạn nấu trong tuần này.',
        startsAt: new Date(Date.now() - 24 * 60 * 60 * 1000),
        endsAt: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000),
        status: 'ACTIVE',
      },
    });
  }

  const challengeRecipes = seededRecipes.filter((recipe) => CHALLENGE_RECIPE_SLUGS.includes(recipe.slug));
  for (const recipe of challengeRecipes) {
    await prisma.challengeEntry.upsert({
      where: { challengeId_recipeId: { challengeId: challenge.id, recipeId: recipe.id } },
      update: {},
      create: { challengeId: challenge.id, recipeId: recipe.id, submittedById: user.id },
    });
  }

  console.log(`Seeded ${categories.length} categories, ${tags.length} tags, ${dishes.length} dishes (${withCover} with cover images) and 1 challenge.`);
}

main().catch(async (error) => {
  console.error(error);
  process.exitCode = 1;
}).finally(async () => {
  await prisma.$disconnect();
});
